out=[]
for i,r in enumerate(S1):
    what,decs,extras=D[i]
    assert len(decs)==len(r['suspicions']),(i,r['unit'])
    ds=[]
    for s,(v,why) in zip(r['suspicions'],decs):
        ds.append({"label":s['label'],"root_cause":s['root_cause'],"lines":s['lines'],"verdict":v,"why":why})
    for (l,rc,ln,v,why) in extras:
        ds.append({"label":l,"root_cause":rc,"lines":ln,"verdict":v,"why":why})
    out.append({"step":2,"unit":r['unit'],"what_it_does":what,"decisions":ds})
open('/home/javad/energy-run/sample-apps/step2.jsonl','w').write("\n".join(json.dumps(x,ensure_ascii=False) for x in out)+"\n")
print(len(out), sum(d['verdict']=='accepted' for x in out for d in x['decisions']))
